import{_ as e,o as n,c as t,a0 as a}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /business-impact-review","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/business-impact-review.md","filePath":"references/skills/business-impact-review.md"}'),s={name:"references/skills/business-impact-review.md"};function l(o,i,c,r,h,u){return n(),t("div",null,[...i[0]||(i[0]=[a('<h1 id="skill-business-impact-review" tabindex="-1">Skill: <code>/business-impact-review</code> <a class="header-anchor" href="#skill-business-impact-review" aria-label="Permalink to &quot;Skill: `/business-impact-review`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>business-impact-review</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/business-impact-review</code></li><li>Lệnh mang tính chất phân tích (Read-only analysis), Agent tuyệt đối không tự ý sửa code nếu không được yêu cầu.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc thông tin cấu hình Multi-repo của nền tảng FlowGrid (ví dụ: <code>dna/platform.json</code> cho hệ thống mới, hoặc <code>dna/legacy.json</code> cho hệ thống cũ).</li><li>Nhận diện các phương thức (methods), API routes, Jobs, Events, Listeners vừa bị thay đổi.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra Báo cáo Đánh giá tác động (Blast-radius review).</li><li>Báo cáo phải bao gồm: <ul><li>Khuyến nghị có nên Deploy (Ship recommendation).</li><li>Danh sách các symbols/functions bị ảnh hưởng.</li><li>Phân tích Caller theo chiều ngang (Horizontal callers).</li><li>Phân tích Luồng quy trình theo chiều dọc (Vertical process paths).</li><li><strong>Báo cáo tác động ranh giới (Cross-Boundary Impact - FE/BE &amp; Surfaces).</strong></li><li>Rủi ro/Nợ kỹ thuật còn sót (Residual risks).</li><li>Kế hoạch Test tập trung (Targeted test plan).</li></ul></li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng phân tích rủi ro hệ thống trước khi Deploy hoặc khi thay đổi lõi nghiệp vụ.</li><li><strong>Quét xuyên biên giới (Cross-Boundary Scan):</strong><ul><li><strong>Cross-repo (FE ↔ BE):</strong> Nếu sửa API ở BE, phải quét xem FE gọi API đó có bị gãy contract không. Ngược lại, nếu FE đổi form payload, phải xem BE có parse lỗi không.</li><li><strong>Cross-surface (Surface A ↔ Surface B):</strong> Nếu sửa logic ở module A (vd: phát sinh event mới hoặc đổi DB schema), phải dùng CodeGraph truy vết xem module B (listener/consumer) có dính side-effect hay không.</li></ul></li><li><strong>Trace luồng dọc (Vertical Path Trace):</strong> Agent sẽ truy vết từ <code>Client/FE -&gt; Route -&gt; Auth/Middleware -&gt; Controller -&gt; Service -&gt; DB -&gt; Event -&gt; API bên ngoài</code>.</li><li><strong>Phân loại rủi ro (Risk Classes):</strong> Đánh giá các lỗ hổng về phân quyền (AuthZ/IDOR), thiếu xác thực dữ liệu rỗng (Null/Empty), nuốt lỗi (Error collapsing), hoặc logic bất đồng bộ (Async idempotency).</li><li>Kỹ năng này không sinh ra tài liệu kiến trúc (Architecture Docs) thông thường, mà nó là một dạng &quot;Kiểm toán viên trước giờ G&quot; để đảm bảo không làm sập các hệ thống khác (nhất là trong môi trường Microservices hoặc nhiều repo liên kết).</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Sử dụng các công cụ mạnh mẽ như <code>CodeGraph</code> để truy vết Caller/Callee xuyên suốt các Repository.</li><li>Bổ trợ cực tốt cho chu trình <code>/review</code> và <code>/test</code> ở cuối vòng đời.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/business-impact-review</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=e(s,[["render",l]]);export{g as __pageData,p as default};
